  "d.r70f4w": "THETA-7 གི་ནམ་མཁའ་ 0.5.0 དང་རྡོ་ཚུ་དང་བཅས། རྩེད་མོའི་ནང་གི་པར། པར་རིམ་ 0.5.0",
  "d.rap4k0": "BRAWLER། རྩེད་མོའི་དཀར་ཆག་ལས་གནམ་གྲུ་ཁང་གི་པར། (0.3.0 དང་ དེ་ལས་ཤུལ་མའི་དོན་ལུ་བཟོ་མི་གྲུ་ཁོག། ངོ་མའི་ཚད་ 256 x 128།) རྩེད་མོའི་ནང་གི་པར། པར་རིམ་ 0.6.1",
  "d.reost1": "སྲུང་ཤུབས་ཅན་གྱི་འཐབ་གནམ་གྲུ་ཅིག་གིས་དམིགས་ཡུལ་གྱི་སྒྲོམ་ལུ་ལེ་ཟར་འོད་ཟེར་འཕེན་བཞིན་པ།",
  "d.rexwmq": "འཕེན་ནིའི་དོན་ལུ་ཨེབ་ཚད་བཟུང་། གནམ་གྲུའི་མེ་ཚོགས་ཚུ་བསྐྱར་འཕེན་བར་ཐག་རེ་རེ་ལུ་སྐབས་བསྒྱུར་འབད་དོ། ད་ལྟོའི་ཚོགས་ནང་གི་གཏན་འཇགས་མེ་མདའ་དང་ལེ་ཟར་མེ་མདའ་ཆ་མཉམ་གྱིས་འཕེན་འོང་།",
  "d.sdtkzv": "ORION-1 གི་དོན་ལུ་ LOADOUT གསལ་གཞི། གྲུ་ཁོག་དང་སྲུང་ཤུབས་ཀྱི་རིམ་པ། སྲུང་ཤུབས་ཚོན་མདོག་དང་མཚོན་ཆ་བཀལ་སའི་ཕྲེང་ཚུ་དང་བཅས།",
  "d.sp0f4k": "སྲུང་ཤུབས་སྐྱེད་ཆས་ཀྱི་རིམ་པ་ 3 (STANDARD EMITTER, HARDENED EMITTER, DEEP-FIELD EMITTER) སྤྲོད་དོ།",
  "d.sudba1": "ཉེ་འཁོར་སྲུང་སྐྱོབ།",
  "d.svcsep": "ས་འཐེན་ 1.62 m/s2 (0.165 g)།",
  "d.taax41": "Orion-81 ལོགོ། འོད་འཚེར་བའི་སྔོན་པོ་དཀར་པོའི་སྐར་མ་གསུམ་ དངུལ་གྱི་སྒྲོམ་ཟླུམ་པོ་ཅིག་གི་ནང་།",
  "d.tbfe8v": "དཔེ་གཟུགས་ཚུ་བསགས་ཡོད། པར་རིས་དེབ་ཚུ་བཟོ་ཡོད།",
  "d.tg0hgk": "THETA-7 གྲུ་ཆོམ་གྱི་ཐང་གི་འཁོར་ཡོད་པའི་གླིང་ཁ་ཅན་གྱི་རྡོ་ཚུ།",
  "d.tg8bac": "MERIDIAN འདི་ རྩེད་མོའི་གནམ་གྲུ་ཁང་གི་དཀར་ཆག་ནང་སྟོན་པ་བཞིན། པར་རིམ་ 0.6.1 གྲུ་ཁོག ནག་པོའི་ཐོག་ལུ་ཕྱོགས་བཞི་ཆ་གསུམ་གྱི་མཐོང་སྣང་།",
  "d.tg8pdz": "སྲུང་ཤུབས་ཀྱི་ཚོན་མདོག་ 8 དང་ རང་འདོད་ཀྱི་ཚོན་མདོག་ཅིག་སྤྲོད་དོ།",
  "d.th2bvi": "ཆ་ཤས་ཚུ་རིམ་པ་བཞིན་དུ། L1 གནམ་གྲུའི་རིགས་ཨང་། གྲུ་ཁོག་ཨང་ + སྲུང་ཤུབས་ཨང་། ཚོན་མདོག མཚོན་ཆ་བཀལ་སའི་རྟགས། གནམ་གྲུ་ཆུང་ཀུའི་ཨང་། གནམ་གྲུ་ཆུང་ཀུའི་གྲུ་ཁོག་ཨང་ + གནམ་གྲུ་ཆུང་ཀུའི་སྲུང་ཤུབས་ཨང་། གནམ་གྲུ་ཆུང་ཀུའི་མཚོན་ཆ་བཀལ་སའི་རྟགས། ཚོན་མདོག་ STOCK གི་དོན་ལུ་ '-' ཡང་ན་ ཚོན་ཐོག་རྣམ་གྲངས་ k གི་དོན་ལུ་ 'p<k>' ཡང་ན་ བཅུ་དྲུག་རིམ་གྱི་ཨང་དྲུག (ཡིག་ཆུང་།) ཆ་ཤས་ཅིག་འདི་ '00' (རིམ་པ།) '-' (ཚོན་མདོག གནམ་གྲུ་ཆུང་ཀུ།) ཡང་ན་ སྟོངམ་ (མཚོན་ཆ་བཀལ་ས།) ཨིན་པ་ཅིན་སྔར་སྲོལ་ཨིན། སྔར་སྲོལ་མིན་པའི་མཇུག་མའི་ཤུལ་ལས་ཡོད་པའི་སྔར་སྲོལ་ཆ་ཤས་ཆ་མཉམ་བསལ་དོ། ཧེ་མམ་གྱི་ཚུ་བཞག་དོ། གནམ་གྲུ་ཆུང་ཀུའི་ཆ་ཤས་ཚུ་གནམ་གྲུ་ཁང་ཅན་གྱི་རིགས་ལུ་རྐྱངམ་གཅིག་ཡོད། རིགས་ཀྱིས་ལེན་མི་ཚུགས་པའི་གདམ་ཁ་འདི་ STOCK སྦེ་ལྷག་དོ།",
  "d.tjh47s": "ཚོགས་ཀྱི་མེ་འཕེན་རེ་རེ་དང་གཅིག་ཁར་ཚ་བ་འཕར་དོ། མེ་མདའ་ཚུ་ཚད་ཐུག་པའི་སྐབས་ཚ་བཀྲེལ་ཞིནམ་ལས་ ཚད་དེ་ལས་དམའ་བའི་ཁར་སླར་གསོ་འབདཝ་ཨིན།",
  "d.tnqgr2": "GPL ཚོད་ལྟའི་པར་རིམ་ལས་སྤོ་བའི་རྩེད་མོའི་ཀོཌ།",
