  "why.anthropic": "Anthropic གི་དོན་ལུ།",
  "why.anthropicSEconomic": "<0>Anthropic གི་དཔལ་འབྱོར་གྱི་ཁྱད་ཕུད་ཐོ་གཞུང་ (<1/>)<\/0> ལས་ ལཱ་གི་འགོ་བཙུགས་པའི་མི་ཚུ་གིས་ཁོང་གི་ལཱ་མང་ཤོས་ཨེ་ཨའི་གིས་འབད་ཚུགས་པ་མཐོང་ཡོད།",
  "why.anthropicSEconomic2": "<0>Anthropic གི་དཔལ་འབྱོར་སྲིད་བྱུས་ཀྱི་གཞི་བཀོད་ (<1/>)<\/0> གིས་ཁེ་ལས་ཚུ་ལུ་མི་ཚུ་བཅད་ནི་གི་ཚབ་ལུ་ ལོག་སློབ་སྦྱོང་དང་ཚབ་སྤྱོད་འབད་ནི་ལུ་ཞུ་དོ།",
  "why.anthropicSReview": "<0>Anthropic གི་ལོག་སློབ་སྦྱོང་གི་ཁུངས་སྐྱེལ་བསྐྱར་ཞིབ་ (<1/>)<\/0> ལས་ ལཱ་བཀོལ་པ་དང་འབྲེལ་བའི་ཁྱབ་ཁོངས་དམིགས་བསལ་གྱི་ལས་རིམ་ཚུ་ཁྱད་པར་ཅན་སྦེ་ལཱ་འབད་མི་མཐོང་ཡོད།",
  "why.askSimpleFive": "ཞུ་བ་འདི་སྟབས་བདེ་ཨིན། འགོ་བཙུགས་ནིའི་དོན་ལུ་ Claude གི་སྡོད་ཁྲི་ལྔ། གཞི་འཛུགས་པ་གིས་ཁོང་ཚུ་ལུ་ལྕོགས་ཅན་དང་སྤྲོ་བ་ཅན་གྱི་མི་ཚུ་བཀང་ཚུགས་པ་ཅིན་ ཨེ་ཨའི་འདི་སེམས་ཚུལ་ལེགས་ཤོམ་དང་བཅས་ ཡིད་དུ་འོང་བའི་དངོས་པོ་ཅིག་བཟོ་ནི་ལུ་ག་དེ་སྦེ་ལག་ལེན་འཐབ་ཚུགས་ག་ང་ཚོ་གིས་སྟོན་འོང་།",
  "why.context": "རྒྱབ་ལྗོངས།",
  "why.designersEngineers": "པར་རིས་བཟོ་མི་དང་མཉམ་སྒྲིག་པའི་དོན་ལུ།",
  "why.everyItemBelow": "འོག་གི་རྣམ་གྲངས་རེ་རེ་འདི་ འཆར་གཞི་ཅིག་ཨིན་ཡང་ན་ ད་ལྟོ་ཡང་ཁྱབ་བསྒྲགས་འབད་ནི་ལྷག་འདུག འདི་ནང་ཅི་ཡང་གྲོས་མཐུན་མ་འབད། གྲངས་ཅིག་ཡང་ཁས་མི་ལེན།",
  "why.founderWentFrom": "གཞི་འཛུགས་པ་ཅིག་གིས་ཚོད་ལྟའི་པར་རིམ་ལས་ 0.6.1 ཚུན་ ཉིནམ་ <0/> ནང་ལྷོད། ལཱ་ལུ་མཁོ་མི་ཚོགས་པ་ལྔ་གིས་ག་ཅི་འབད་ཚུགས་ག་བསམ།",
  "why.fromAnthropic": "Anthropic ལས།",
  "why.fromBackers": "རྒྱབ་སྐྱོར་པ་ཚུ་ལས།",
  "why.fullyDisclosedAi": "ཨེ་ཨའི་གིས་བཟོ་མི་རྩེད་མོ་ཅིག ཧྲིལ་པོ་ཁྱབ་བསྒྲགས་འབད་ཡོད། རྩེད་མི་ཚུ་གིས་ཞིབ་འཇུག་འབད་ཚུགས་པའི་དམིགས་ཡུལ་དང་བཅས། Unreal Engine 5 ལུ་སྤོ་ནིའི་འཆར་གཞི་ཡོད། (འགྲུལ་ལམ་གྱི་རིམ་པ་ 3།)",
  "why.fullyDocumentedExample": "འཁོར་ཆས་ལས་རྩེད་མོ་ཚུན་ ལས་བྱེད་ཀྱི་བཟོ་བསྐྲུན་གྱི་དཔེ་ཅིག ཧྲིལ་པོ་ཟིན་ཐོ་བཀོད་འབད་ཡོད། (ཡིག་མཛོད། རྗེས་འདེད་ཐོ་གཞུང་དང་པར་རིམ་བསྒྱུར་བཅོས་མེད་པར་བཞག་མི་རེ་རེ་ཉར་ཚགས་འབད་ཡོད།) དེ་ལས་ཨེ་ཨའི་གི་ཁེ་ཕན་གྱིས་ཁོ་གིས་བསྟན་པའི་མི་ཚུ་ལུ་གླ་ཆ་སྤྲོད་ཚུགས་པའི་ཐབས་ལམ་གཅིག་གི་ཚོད་ལྟ་ཆུང་ཀུ་ལག་ལེན་ཅན་ཅིག།",
  "why.fundingGoalAnnounced": "དངུལ་བསྡུ་ནིའི་དམིགས་ཡུལ། ཁྱབ་བསྒྲགས་འབད་ནི་ལྷག་འདུག",
  "why.kickstarterRoadmapPhase": "Kickstarter (འགྲུལ་ལམ་གྱི་རིམ་པ་ 5) འདི་ མི་མང་གི་དངུལ་བསྡུ་ནིའི་སྐོར་དང་པོ་ཨིན། ཁོ་གི་དངུལ་འདི་ ཨེ་ཨའི་གིས་ལཱ་བརླག་སོང་མི་ གོང་འཕེལ་པ་དང་པར་རིས་བཟོ་མི་དང་པོ་ཚུ་ལཱ་བཀོལ་ནིའི་དོན་ལུ་ཨིན། (རིམ་པ་ 6།) ཁོང་ཚུ་གིས་ཨེ་ཨའི་གིས་བཟོ་མི་རྒྱུ་དངོས་ཚུ་གཅིག་རེ་རེ་ཚབ་བཟོ་འོང་། <0>སྐོར་དང་པོ་གིས་ག་ཅི་གི་དོན་ལུ་སྤྲོད་ག ལས་འགན་རེ་རེ་བཞིན། ཁྱབ་བསྒྲགས་འབད་ནི་ལྷག་འདུག<\/0>",
  "why.linksContextOnly": "ལིངས་ཀྲི་ཚུ་རྒྱབ་ལྗོངས་རྐྱངམ་གཅིག་གི་དོན་ལུ་ཨིནམ་ལས་ ངོས་ལེན་ཅིག་མི་སྟོན།",
  "why.n06WhyMatters": "06 · དོན་ཅི་ལུ་གལ་ཆེ།",
  "why.orion81Tests": "Orion-81 གིས་བསམ་འཆར་དེ་གི་ཐབས་ལམ་ཆུང་ཀུ་ཅིག་ཚོད་ལྟ་འབདཝ་ཨིན། འདི་ འཆར་གཞི་ཅིག་ཨིན། ད་ལྟོ་ཡང་ལཱ་བཀོལ་མེད།",
  "why.plannedPaidCredited": "འཆར་གཞི: འཛིན་ཁུངས་དང་འཁྲིལ་ཏེ་ གླ་ཆ་དང་མིང་བཀོད་པའི་ལཱ་གིས་ཨེ་ཨའི་གིས་བཟོ་མི་རྒྱུ་དངོས་ཚུ་གཅིག་རེ་རེ་ཚབ་བཟོ།",
  "why.publishersEngineMakers": "དཔར་སྐྲུན་པ་དང་འཁོར་ཆས་བཟོ་མི་ཚུ་གི་དོན་ལུ།",
  "why.routesThatExist": "Anthropic གི་མི་མང་གི་ལས་རིམ་ནང་ཡོད་པའི་ལམ་ཚུ་ནང་ Claude for Startups (ཁྱད་ཆོས་དང་ Applied AI གི་ལས་ཀའི་ཆུ་ཚོད།) དང་ Claude Founder House གི་ལས་རིམ་ཚུ་འཁོད་ཡོད། Orion-81 འདི་ ཨེ་ཨའི་གིས་དངུལ་སྤྲོད་མི་ལཱ་ལོག་བཀོལ་ཚུལ་སློབ་ཞིབ་འབད་མི་ཞིབ་འཇུག་པ་ཚུ་གི་དོན་ལུ་ཞིང་ཚུགས་ཀྱི་ས་ཅིག་ཡང་འོང་ཚུགས། གྲོས་མཐུན་ཡང་ན་ ངོས་ལེན་ཅི་ཡང་མེད།",
  "why.studyingAiFunded": "ཨེ་ཨའི་གིས་དངུལ་སྤྲོད་མི་ལཱ་ལོག་བཀོལ་ཚུལ་སློབ་ཞིབ་འབད་དོ་ག? <0>འབྲེལ་ལམ་གྱི་ཁ་གསལ་མགྱོགས་པོ་འོང་འོང་།<\/0>",
